  "Add a note": ["Додати нотатку", "Añadir una nota", "添加笔记", "नोट जोड़ें", "إضافة ملاحظة", "নোট যোগ করুন", "Ajouter une note", "Tambah catatan", "Adicionar nota", "メモを追加"],
  "Add a note…": ["Додати нотатку…", "Añadir una nota…", "添加笔记…", "नोट जोड़ें…", "إضافة ملاحظة…", "নোট যোগ করুন…", "Ajouter une note…", "Tambah catatan…", "Adicionar nota…", "メモを追加…"],
  "Add a voice": ["Додати голос", "Añadir una voz", "添加声音", "आवाज़ जोड़ें", "إضافة صوت", "কণ্ঠ যোগ করুন", "Ajouter une voix", "Tambah suara", "Adicionar voz", "音声を追加"],
  "Add a voice print": ["Додати відбиток голосу", "Añadir huella de voz", "添加声纹", "वॉइस प्रिंट जोड़ें", "إضافة بصمة صوت", "ভয়েস প্রিন্ট যোগ করুন", "Ajouter une empreinte vocale", "Tambah sidik suara", "Adicionar impressão de voz", "声紋を追加"],
  "Add a word": ["Додати слово", "Añadir palabra", "添加词语", "शब्द जोड़ें", "إضافة كلمة", "শব্দ যোগ করুন", "Ajouter un mot", "Tambah kata", "Adicionar palavra", "単語を追加"],
  "Add action item": ["Додати завдання", "Añadir tarea", "添加待办事项", "काम जोड़ें", "إضافة مهمة", "কাজ যোগ করুন", "Ajouter une action", "Tambah tindak lanjut", "Adicionar tarefa", "タスクを追加"],
  "Add action item (A, or Ctrl + Enter in the note). Type what to do now or later.": ["Додати завдання (A або Ctrl + Enter у примітці). Опишіть зараз чи пізніше.", "Añadir tarea (A, o Ctrl + Intro en la nota). Escribe qué hacer ahora o después.", "添加待办事项（A，或在备注中按 Ctrl + Enter）。现在或稍后填写内容。", "काम जोड़ें (A, या नोट में Ctrl + Enter)। क्या करना है अभी या बाद में लिखें।", "إضافة مهمة (A، أو Ctrl + Enter في الملاحظة). اكتب ما يجب فعله الآن أو لاحقًا.", "কাজ যোগ করুন (A, বা নোটে Ctrl + Enter)। কী করতে হবে এখন বা পরে লিখুন।", "Ajouter une action (A, ou Ctrl + Entrée dans la note). Écrivez quoi faire maintenant ou plus tard.", "Tambah tindak lanjut (A, atau Ctrl + Enter di catatan). Tulis tugasnya sekarang atau nanti.", "Adicionar tarefa (A, ou Ctrl + Enter na nota). Escreva o que fazer agora ou depois.", "タスクを追加（A、またはメモ内で Ctrl + Enter）。内容は今でも後でも入力できます。"],
  "Add action item, even while typing": ["Додати завдання, навіть під час друку", "Añadir tarea, incluso escribiendo", "输入时也可添加待办事项", "काम जोड़ें, टाइप करते हुए भी", "إضافة مهمة، حتى أثناء الكتابة", "কাজ যোগ করুন, টাইপ করার সময়ও", "Ajouter une action, même en tapant", "Tambah tindak lanjut, bahkan saat mengetik", "Adicionar tarefa, mesmo digitando", "入力中でもタスクを追加"],
  "Add action item, when not typing": ["Додати завдання, коли не друкуєте", "Añadir tarea, sin escribir", "未输入时添加待办事项", "काम जोड़ें, टाइप न करते समय", "إضافة مهمة، عند عدم الكتابة", "কাজ যোগ করুন, টাইপ না করার সময়", "Ajouter une action, hors saisie", "Tambah tindak lanjut, saat tidak mengetik", "Adicionar tarefa, sem digitar", "入力していないときにタスクを追加"],
  "Add another language to translate into it.": ["Додайте ще одну мову, щоб перекладати на неї.", "Añade otro idioma para traducir a él.", "添加其他语言以便翻译成该语言。", "इसमें अनुवाद के लिए एक और भाषा जोड़ें।", "أضف لغة أخرى للترجمة إليها.", "এতে অনুবাদ করতে আরেকটি ভাষা যোগ করুন।", "Ajoutez une autre langue pour y traduire.", "Tambah bahasa lain untuk menerjemahkan ke dalamnya.", "Adicione outro idioma para traduzir para ele.", "翻訳先にする言語をもう 1 つ追加してください。"],
  "Add another recording of this meeting, like from a phone, as a track": ["Додати інший запис цієї зустрічі, наприклад із телефона, як доріжку", "Añadir otra grabación de esta reunión, como la de un teléfono, como pista", "添加此会议的其他录音（如手机录音）作为音轨", "इस मीटिंग की एक और रिकॉर्डिंग, जैसे फ़ोन से, ट्रैक के रूप में जोड़ें", "أضف تسجيلًا آخر لهذا الاجتماع، مثل تسجيل هاتف، كمسار", "এই মিটিংয়ের আরেকটি রেকর্ডিং, যেমন ফোন থেকে, ট্র্যাক হিসেবে যোগ করুন", "Ajouter un autre enregistrement de cette réunion, comme celui d’un téléphone, en piste", "Tambah rekaman lain dari rapat ini, seperti dari ponsel, sebagai trek", "Adicionar outra gravação desta reunião, como de um telefone, como faixa", "この会議の別の録音（電話など）をトラックとして追加"],
  "Add bookmark": ["Додати закладку", "Añadir marcador", "添加书签", "बुकमार्क जोड़ें", "إضافة إشارة مرجعية", "বুকমার্ক যোগ করুন", "Ajouter un signet", "Tambah penanda", "Adicionar marcador", "ブックマークを追加"],
