  "Hide commentary": ["Сховати коментар", "Ocultar comentario", "隐藏评注", "टिप्पणी छिपाएँ", "إخفاء التعليق", "মন্তব্য লুকান", "Masquer le commentaire", "Sembunyikan komentar", "Ocultar comentário", "解説を隠す"],
  "Hide them": ["Сховати", "Ocultarlas", "隐藏", "इन्हें छिपाएँ", "إخفاؤها", "এগুলো লুকান", "Les masquer", "Sembunyikan", "Ocultá-los", "隠す"],
  "Hide tracks": ["Сховати доріжки", "Ocultar pistas", "隐藏音轨", "ट्रैक छिपाएँ", "إخفاء المسارات", "ট্র্যাক লুকান", "Masquer les pistes", "Sembunyikan trek", "Ocultar faixas", "トラックを隠す"],
  "Hide translation": ["Сховати переклад", "Ocultar traducción", "隐藏翻译", "अनुवाद छिपाएँ", "إخفاء الترجمة", "অনুবাদ লুকান", "Masquer la traduction", "Sembunyikan terjemahan", "Ocultar tradução", "翻訳を隠す"],
